import java.util.Scanner;

public class Main {
    static long res = 0;

    static int num(long n) {
        int count = 0;
        while (n != 0) {
            n /= 10;
            count++;
        }
        return count;
    }

    static long find(long n) {
        int ex = num(n);
        long cur = 0, ad = 1;
        for (int i = 0; i <= ex - 1; i++) {
            cur += ad;
            ad *= 10;
        }
        if (cur <= n)
            return cur;
        return ((cur - 1) / 10);
    }

    static long process(long n) {
        if (n <= 6) {
            return n;
        }
        if (n <= 11)
            return (13 - n);
        long tmp = find(n);
        long more = tmp * 10 + 1;
        if (n % tmp == 0) {
            long t = n / tmp;
            if (n <= more / 2 + tmp)
                return num(tmp) * t;
            else {
                long cur = process(more - n);
                return num(more) + cur;
            }
        } else {
            long _m = (n / tmp) * tmp;
            long _M = (n / tmp + 1) * tmp;
            long res = process(_m) + process(n - _m);
            if (n > more / 2)
                res = Math.min(process(_m) + process(n - _m), num(more) + process(more - n));
            return res;
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        long n = scanner.nextLong();
        System.out.println(process(n));
        scanner.close();
    }
